const (
	// A128CBC_HS256 is AES-128 in CBC mode with HMAC-SHA-256 (truncated to
	// 128 bits); the CEK is 32 octets.
	A128CBC_HS256 = "A128CBC-HS256"
	// A192CBC_HS384 is AES-192 in CBC mode with HMAC-SHA-384 (truncated to
	// 192 bits); the CEK is 48 octets.
	A192CBC_HS384 = "A192CBC-HS384"
	// A256CBC_HS512 is AES-256 in CBC mode with HMAC-SHA-512 (truncated to
	// 256 bits); the CEK is 64 octets.
	A256CBC_HS512 = "A256CBC-HS512"
	// A128GCM is AES-128 in Galois/Counter Mode; the CEK is 16 octets.
	A128GCM = "A128GCM"
	// A192GCM is AES-192 in Galois/Counter Mode; the CEK is 24 octets.
	A192GCM = "A192GCM"
	// A256GCM is AES-256 in Galois/Counter Mode; the CEK is 32 octets.
	A256GCM = "A256GCM"
)

const (
	// RSA1_5 is RSAES-PKCS1-v1_5. It is supported for interoperability with
	// existing deployments (and the RFC 7520 §5.1 vector) but is vulnerable
	// to Bleichenbacher-style attacks; prefer RSA-OAEP-256.
	RSA1_5 = "RSA1_5"
	// RSA_OAEP is RSAES-OAEP using SHA-1 and MGF1 with SHA-1.
	RSA_OAEP = "RSA-OAEP"
	// RSA_OAEP_256 is RSAES-OAEP using SHA-256 and MGF1 with SHA-256.
	RSA_OAEP_256 = "RSA-OAEP-256"
	// A128KW is AES Key Wrap (RFC 3394) with a 128-bit key.
	A128KW = "A128KW"
	// A192KW is AES Key Wrap (RFC 3394) with a 192-bit key.
	A192KW = "A192KW"
	// A256KW is AES Key Wrap (RFC 3394) with a 256-bit key.
	A256KW = "A256KW"
	// Dir uses the supplied symmetric key directly as the content
	// encryption key; no key is transmitted.
	Dir = "dir"
	// ECDH_ES is Elliptic Curve Diffie-Hellman Ephemeral Static key
	// agreement using Concat KDF; the agreed key is the CEK.
	ECDH_ES = "ECDH-ES"
	// ECDH_ES_A128KW agrees a 128-bit key with ECDH-ES and uses it to wrap
	// the CEK with AES Key Wrap.
	ECDH_ES_A128KW = "ECDH-ES+A128KW"
	// ECDH_ES_A192KW agrees a 192-bit key with ECDH-ES and uses it to wrap
	// the CEK with AES Key Wrap.
	ECDH_ES_A192KW = "ECDH-ES+A192KW"
	// ECDH_ES_A256KW agrees a 256-bit key with ECDH-ES and uses it to wrap
	// the CEK with AES Key Wrap.
	ECDH_ES_A256KW = "ECDH-ES+A256KW"
	// A128GCMKW wraps the CEK with AES-128 in GCM mode.
	A128GCMKW = "A128GCMKW"
	// A192GCMKW wraps the CEK with AES-192 in GCM mode.
	A192GCMKW = "A192GCMKW"
	// A256GCMKW wraps the CEK with AES-256 in GCM mode.
	A256GCMKW = "A256GCMKW"
	// PBES2_HS256_A128KW derives a key from a password with
	// PBKDF2-HMAC-SHA-256 and wraps the CEK with A128KW.
	PBES2_HS256_A128KW = "PBES2-HS256+A128KW"
	// PBES2_HS384_A192KW derives a key from a password with
	// PBKDF2-HMAC-SHA-384 and wraps the CEK with A192KW.
	PBES2_HS384_A192KW = "PBES2-HS384+A192KW"
	// PBES2_HS512_A256KW derives a key from a password with
	// PBKDF2-HMAC-SHA-512 and wraps the CEK with A256KW.
	PBES2_HS512_A256KW = "PBES2-HS512+A256KW"
)

const (
	// HS256 is HMAC using SHA-256; the key is a []byte secret.
	HS256 = "HS256"
	// HS384 is HMAC using SHA-384; the key is a []byte secret.
	HS384 = "HS384"
	// HS512 is HMAC using SHA-512; the key is a []byte secret.
	HS512 = "HS512"
	// RS256 is RSASSA-PKCS1-v1_5 using SHA-256.
	RS256 = "RS256"
	// RS384 is RSASSA-PKCS1-v1_5 using SHA-384.
	RS384 = "RS384"
	// RS512 is RSASSA-PKCS1-v1_5 using SHA-512.
	RS512 = "RS512"
	// PS256 is RSASSA-PSS using SHA-256 and MGF1 with SHA-256.
	PS256 = "PS256"
	// PS384 is RSASSA-PSS using SHA-384 and MGF1 with SHA-384.
	PS384 = "PS384"
	// PS512 is RSASSA-PSS using SHA-512 and MGF1 with SHA-512.
	PS512 = "PS512"
	// ES256 is ECDSA using P-256 and SHA-256.
	ES256 = "ES256"
	// ES384 is ECDSA using P-384 and SHA-384.
	ES384 = "ES384"
	// ES512 is ECDSA using P-521 and SHA-512.
	ES512 = "ES512"
	// EdDSA is Edwards-curve DSA using Ed25519.
	EdDSA = "EdDSA"
	// None is the unsecured "none" algorithm. This package never verifies a
	// JWS that uses it; the constant exists so callers can detect it.
	None = "none"
)

const (
	// UseSig marks a key intended for signing and verification.
	UseSig = "sig"
	// UseEnc marks a key intended for encryption and key management.
	UseEnc = "enc"
)

const (
	// DefaultPBES2Count is the PBKDF2 iteration count used when a caller does
	// not set "p2c" explicitly.
	DefaultPBES2Count = 100000

	// MinPBES2Count is the smallest iteration count this package will accept
	// when decrypting. RFC 7518 §4.8.1.2 recommends a minimum of 1000.
	MinPBES2Count = 1000

	// MaxPBES2Count is the largest iteration count this package will accept.
	// The "p2c" header is attacker-controlled, so an unbounded count is a
	// denial-of-service vector: a token asking for a billion iterations would
	// pin a CPU for minutes before any authentication happens.
	MaxPBES2Count = 1000000

	// MaxPBES2SaltInput is the largest "p2s" salt input accepted, again to
	// bound work driven by attacker-supplied headers.
	MaxPBES2SaltInput = 1024
)

