var (
	// ErrInvalidToken is a generic error indicating a JWS or JWE could not be
	// parsed or is otherwise malformed.
	ErrInvalidToken = errors.New("jose: token is invalid")

	// ErrMalformed indicates the compact or JSON serialization did not have
	// the structure required by RFC 7515 / RFC 7516, or a part failed to
	// base64url-decode.
	ErrMalformed = errors.New("jose: token is malformed")

	// ErrSignatureInvalid indicates a JWS signature or MAC failed verification.
	ErrSignatureInvalid = errors.New("jose: signature is invalid")

	// ErrDecryptFailed indicates a JWE could not be decrypted: the key was
	// wrong, the authentication tag did not match, or the content was
	// corrupt. The cause is deliberately not distinguished.
	ErrDecryptFailed = errors.New("jose: decryption failed")

	// ErrInvalidKeyType indicates the key supplied to an algorithm was not of
	// the Go type that algorithm requires. This is the error that closes
	// algorithm-confusion attacks.
	ErrInvalidKeyType = errors.New("jose: key is of invalid type")

	// ErrInvalidKey indicates a JWK could not be decoded into a usable key, or
	// held inconsistent or out-of-range parameters.
	ErrInvalidKey = errors.New("jose: key is invalid")

	// ErrKeyNotFound indicates a JWK Set did not contain a key matching the
	// requested key ID.
	ErrKeyNotFound = errors.New("jose: no key found for kid")

	// ErrUnsupportedAlgorithm indicates the "alg" header named a signature or
	// key-management algorithm this package does not implement.
	ErrUnsupportedAlgorithm = errors.New("jose: unsupported algorithm")

	// ErrUnsupportedEncryption indicates the "enc" header named a content
	// encryption algorithm this package does not implement.
	ErrUnsupportedEncryption = errors.New("jose: unsupported content encryption algorithm")

	// ErrNoneAlgDisallowed indicates a JWS used the unsecured "none"
	// algorithm. This package never verifies such a token.
	ErrNoneAlgDisallowed = errors.New("jose: 'none' algorithm is not allowed")

	// ErrInvalidCrit indicates the JOSE "crit" header listed an extension the
	// caller has not declared as understood, or was itself malformed.
	ErrInvalidCrit = errors.New("jose: unsupported or malformed 'crit' header")

	// ErrInvalidHeader indicates a JOSE header was missing a required
	// parameter or held a parameter of the wrong JSON type.
	ErrInvalidHeader = errors.New("jose: invalid JOSE header")

	// ErrCompressionLimit indicates a "zip":"DEF" payload expanded past
	// MaxDecompressedSize, which is how this package refuses decompression
	// bombs.
	ErrCompressionLimit = errors.New("jose: decompressed payload exceeds limit")

	// ErrIterationCount indicates a PBES2 "p2c" header requested more PBKDF2
	// iterations than MaxPBES2Count permits, a denial-of-service vector when
	// the count is attacker-supplied.
	ErrIterationCount = errors.New("jose: PBES2 iteration count out of range")

	// ErrDetachedPayload indicates a compact JWS carried no payload and the
	// caller supplied none out of band. See VerifyOptions.DetachedPayload.
	ErrDetachedPayload = errors.New("jose: payload is detached")
)

types.signature:
type DecryptOptions struct {
	// Algorithms, when non-empty, restricts the accepted key management
	// "alg" values.
	Algorithms []string

	// Encryptions, when non-empty, restricts the accepted content
	// encryption "enc" values.
	Encryptions []string

	// KnownCritical lists extension header names the caller understands.
	// Any other name in "crit" causes rejection.
	KnownCritical []string

	// MaxDecompressed overrides MaxDecompressedSize for this call. Values
	// below or equal to zero select the default.
	MaxDecompressed int
}

type EncryptOptions struct {
	// Algorithm is the JWE key management "alg" value, e.g. "RSA-OAEP-256",
	// "A128KW", "dir", or "ECDH-ES+A256KW". When empty, Encrypt infers a
	// conventional algorithm for the key's type.
	Algorithm string

	// Encryption is the content encryption "enc" value, e.g. "A256GCM" or
	// "A128CBC-HS256". It defaults to A256GCM.
	Encryption string

	// KeyID, when non-empty, is written to the protected "kid" header.
	KeyID string

	// Header holds additional protected header parameters. Algorithm inputs
	// may be supplied here — "apu"/"apv" for ECDH-ES, "p2s"/"p2c" for
	// PBES2 — and algorithm outputs ("epk", "iv", "tag", and the generated
	// "p2s"/"p2c") are written back into the protected header.
	Header map[string]any

	// AdditionalHeaders holds further protected header parameters, merged
	// after Header. The compact serialization has no unprotected header, so
	// both maps end up protected and covered by the authentication tag.
	AdditionalHeaders map[string]any

	// Unprotected holds the JWE Shared Unprotected Header, which is *not*
	// covered by the authentication tag. Only the JSON serializations can
	// carry it, so Encrypt rejects it.
	Unprotected map[string]any

	// AdditionalAuthenticatedData is authenticated but not encrypted, and is
	// carried in the "aad" member. Only the JSON serializations can carry
	// it, so Encrypt rejects it.
	AdditionalAuthenticatedData []byte

	// Compress selects raw DEFLATE compression of the plaintext and sets
	// "zip":"DEF". Compressing attacker-influenced plaintext alongside
	// secrets enables CRIME-style attacks; leave it off unless you know the
	// plaintext is safe to compress.
	Compress bool
}

type JWK struct {
	// Kty is the key type: "RSA", "EC", "OKP", or "oct".
	Kty string `json:"kty"`
	// Use is the intended public key use, "sig" or "enc" (optional).
	Use string `json:"use,omitempty"`
	// Alg is the algorithm intended for use with this key, e.g. "RS256".
	Alg string `json:"alg,omitempty"`
	// Kid is the key ID, matched against a JOSE "kid" header.
	Kid string `json:"kid,omitempty"`
	// Crv is the curve name for EC and OKP keys, e.g. "P-256" or "Ed25519".
	Crv string `json:"crv,omitempty"`

	// KeyOps lists the permitted key operations (optional).
	KeyOps []string `json:"key_ops,omitempty"`

	// N is the RSA modulus.
	N string `json:"n,omitempty"`
	// E is the RSA public exponent.
	E string `json:"e,omitempty"`
	// D is the RSA private exponent, or the EC/OKP private key.
	D string `json:"d,omitempty"`
	// P is the first RSA prime factor.
	P string `json:"p,omitempty"`
	// Q is the second RSA prime factor.
	Q string `json:"q,omitempty"`
	// DP is the RSA CRT exponent d mod (p-1).
	DP string `json:"dp,omitempty"`
	// DQ is the RSA CRT exponent d mod (q-1).
	DQ string `json:"dq,omitempty"`
	// QI is the RSA CRT coefficient q^-1 mod p.
	QI string `json:"qi,omitempty"`
	// X is the EC x coordinate, or the OKP public key.
	X string `json:"x,omitempty"`
	// Y is the EC y coordinate.
	Y string `json:"y,omitempty"`
	// K is the symmetric key material for kty "oct".
	K string `json:"k,omitempty"`
}

type JWKSet struct {
	// Keys holds the set's keys in document order.
	Keys []*JWK `json:"keys"`
}

type Recipient struct {
	// Key is the recipient's key: a Go crypto key, a []byte symmetric key or
	// PBES2 password, or a *JWK.
	Key any

	// Algorithm is the key management "alg" for this recipient. When empty
	// it is inferred from the key's type, or taken from the *JWK's "alg".
	Algorithm string

	// KeyID, when non-empty, identifies the key in this recipient's
	// unprotected header. A recipient-specific "kid" cannot live in the
	// protected header, which is shared by every recipient.
	KeyID string

	// Header holds additional per-recipient unprotected header parameters.
	// Algorithm outputs that differ per recipient ("epk", "iv", "tag",
	// "p2s", "p2c") are written here.
	Header map[string]any
}

type SignOptions struct {
	// Algorithm is the JWS "alg" value, e.g. "RS256" or "EdDSA". When empty,
	// Sign infers the conventional algorithm for the key's type.
	Algorithm string

	// KeyID, when non-empty, is written to the protected "kid" header.
	KeyID string

	// Header holds additional protected header parameters. They are covered
	// by the signature.
	Header map[string]any

	// Unprotected holds header parameters that are *not* covered by the
	// signature. They can only be carried by the JSON serializations, so
	// Sign (which produces the compact serialization) rejects them.
	Unprotected map[string]any

	// Critical lists the extension header names to advertise in "crit". Each
	// name must also appear in Header.
	Critical []string

	// DetachPayload omits the payload from the serialization (RFC 7515
	// Appendix F). The payload is still covered by the signature and must be
	// supplied out of band at verification time via
	// VerifyOptions.DetachedPayload.
	//
	// Setting Header["b64"] = false additionally selects the RFC 7797
	// unencoded payload option, in which case "b64" must be listed in
	// Critical.
	DetachPayload bool
}

type Signer struct {
	// Key is the signing key: a Go crypto key, a []byte secret, or a *JWK.
	Key any
	// Options configures this signature.
	Options SignOptions
}

type VerifyOptions struct {
	// Algorithms, when non-empty, restricts the accepted "alg" values. This
	// is the strongest defense against algorithm confusion and should be set
	// whenever the expected algorithm is known.
	Algorithms []string

	// KnownCritical lists extension header names the caller understands and
	// processes out of band. "b64" (RFC 7797) is always understood; any other
	// name in "crit" that is not listed here causes rejection.
	KnownCritical []string

	// DetachedPayload supplies the payload for a JWS serialized without one.
	DetachedPayload []byte
}

