	"github.com/malcolmston/jose"
)

func main() {
	password := []byte("correct horse battery staple")

	token, err := jose.Encrypt([]byte("secret note"), password,
		jose.EncryptOptions{
			Algorithm:  jose.PBES2_HS256_A128KW,
			Encryption: jose.A128GCM,
